const prices = { A: 10, B: 25, C: 110, D: 19.99, E: 0.1, F: 100, G: 100.01, H: 33.4, I: 1000 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body) => fetch(`${base}/orders`, { method: 'POST', body: typeof body === 'string' ? body : JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('sums unit price * qty across items', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 3 }]), 95)
})

test('no discount at or below 100', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 100)
})

test('10% discount applies strictly above 100; result is floored', async () => {
  assert.equal(await totalOf([{ sku: 'G', qty: 1 }]), 90) // 90.009 -> 90
  assert.equal(await totalOf([{ sku: 'H', qty: 3 }]), 90) // 100.2 -> 90.18 -> 90
  assert.equal(await totalOf([{ sku: 'I', qty: 1 }]), 900)
})

test('QUIRK: floating-point error in discount loses a whole euro (110 -> 98, not 99)', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 98)
})

test('QUIRK: total is floored to whole euros, cents are dropped', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 19)
})

test('QUIRK: float sum error is floored (0.1 * 3 -> 0)', async () => {
  assert.equal(await totalOf([{ sku: 'E', qty: 3 }]), 0)
})

test('QUIRK: unknown sku / bad qty yields null total rather than an error', async () => {
  const res = await post({ items: [{ sku: 'ZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('order is persisted and retrievable with sequential ids', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('validation: missing/empty items or invalid JSON -> 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }, '{bad']) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('QUIRK: unknown order id returns 200 with error body', async () => {
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown route -> 404', async () => {
  const res = await fetch(`${base}/nothing`)
  assert.equal(res.status, 404)
  assert.deepEqual(await res.json(), { error: 'no route' })
})
EOF
